// reproduce-offscreen-svg-zero.js
// Usage: node reproduce-offscreen-svg-zero.js
'use strict';

const UnusedImages = require('lighthouse/lighthouse-core/audits/byte-efficiency/offscreen-images.js');
const TTIAudit    = require('lighthouse/lighthouse-core/audits/time-to-interactive.js');

// Stub out the TTI audit so that all images are considered loaded before TTI.
const _originalTTI = TTIAudit.audit;
TTIAudit.audit = () => Promise.resolve({
  extendedInfo: {
    value: { timestamps: { timeToInteractive: Infinity } }
  }
});

(async () => {
  // Default viewport size
  const DEFAULT_VIEWPORT = { innerWidth: 1920, innerHeight: 1080 };

  // Build a fake network record for an SVG of some bytes
  const svgRecord = {
    mimeType: 'image/svg+xml',
    startTime:   0,            // before TTI
    resourceSize: 10 * 1024,   // 10 KB
    url: 'https://example.com/img/ring.svg',
  };

  // Simulate an image with zero width/height
  const zeroSizeImage = {
    src: 'https://example.com/img/ring.svg',
    networkRecord: svgRecord,
    clientWidth: 0,
    clientHeight: 0,
    clientRect: { top: 0, left: 0, right: 0, bottom: 0 }
  };

  // Run the audit
  const auditResult = await UnusedImages.audit_({
    ViewportDimensions: DEFAULT_VIEWPORT,
    ImageUsage: [zeroSizeImage]
  });

  console.log('Audit results:', JSON.stringify(auditResult, null, 2));

  // Restore the original TTI audit
  TTIAudit.audit = _originalTTI;
})();
